    var classTotal = count(CONFIG.ciClass, '', [], '');
    var discovered = count(CONFIG.ciClass, 'discovery_source=ServiceNow^ORdiscovery_sourceLIKEService Graph', ['discovery_source'], '');
    var discoveredPct = pct(discovered, classTotal);
