    metric('classes_small_pct', function () { return pct(profile.small, profile.inUse); });
    metric('classes_no_rule', function () { return profile.noRule; });
    metric('dup_tasks_open', function () { return count('reconcile_duplicate_task', 'active=true', ['active'], 'dup_tasks_open'); });
    metric('hw_serial_dup_clusters', function () { return dupClusters('cmdb_ci_hardware', 'serial_number'); });
    metric('ci_class_name_dup_clusters', function () { return dupClusters(CONFIG.ciClass, 'name'); });
